/**
 * Generates supabase/seed.sql from src/lib/catalog.ts and the default
 * pricing rules, so the code catalog and DB seed can't drift.
 *   npm run db:seed:gen
 */
import { writeFileSync } from "node:fs";
import { ADJACENCY, AREAS, GROUPS, SERVICES, SEAT_PRICE_CENTS, slugify } from "../src/lib/catalog";
import { DEFAULT_PRICING, configToRows } from "../src/lib/pricing/defaults";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const lines: string[] = [
  "-- GENERATED by scripts/generate-seed.ts — do not edit by hand.",
  "-- Idempotent: safe to re-run; existing rows are updated in place.",
  "",
  "insert into app_settings (key, value) values",
  "  ('max_seats_per_cell', '2'),",
  "  ('max_partners_per_lead', '2'),",
  `  ('seat_price_cents', '${JSON.stringify(SEAT_PRICE_CENTS)}')`,
  "on conflict (key) do update set value = excluded.value, updated_at = now();",
  "",
  "insert into service_groups (code, name, sort) values",
  GROUPS.map((g, i) => `  (${q(g.code)}, ${q(g.name)}, ${i})`).join(",\n"),
  "on conflict (code) do update set name = excluded.name, sort = excluded.sort;",
  "",
  "insert into services (code, name, slug, group_id, sort) values",
  SERVICES.map(
    (s, i) => `  (${q(s.code)}, ${q(s.name)}, ${q(s.slug)}, (select id from service_groups where code = ${q(s.group)}), ${i})`,
  ).join(",\n"),
  "on conflict (code) do update set name = excluded.name, slug = excluded.slug, group_id = excluded.group_id, sort = excluded.sort;",
  "",
  "insert into areas (code, name, slug, price_tier, sort) values",
  AREAS.map((a, i) => `  (${q(a.code)}, ${q(a.name)}, ${q(a.slug)}, ${q(a.priceTier)}, ${i})`).join(",\n"),
  "on conflict (code) do update set name = excluded.name, slug = excluded.slug, price_tier = excluded.price_tier, sort = excluded.sort;",
  "",
  "insert into suburbs (name, slug, area_id) values",
  AREAS.flatMap((a) =>
    a.suburbs.map((s) => `  (${q(s)}, ${q(slugify(s))}, (select id from areas where code = ${q(a.code)}))`),
  ).join(",\n"),
  "on conflict (slug) do update set name = excluded.name, area_id = excluded.area_id;",
  "",
  "insert into area_adjacency (area_id, adjacent_area_id)",
  "select a.id, b.id from (values",
  Object.entries(ADJACENCY)
    .flatMap(([from, tos]) => tos.map((to) => `  (${q(from)}, ${q(to)})`))
    .join(",\n"),
  ") v(f, t) join areas a on a.code = v.f join areas b on b.code = v.t",
  "on conflict do nothing;",
  "",
  "insert into pricing_rules (key, service_id, rule) values",
  configToRows(DEFAULT_PRICING)
    .map(
      (r) =>
        `  (${q(r.key)}, ${SERVICES.some((s) => s.code === r.key) ? `(select id from services where code = ${q(r.key)})` : "null"}, ${q(JSON.stringify(r.rule))}::jsonb)`,
    )
    .join(",\n"),
  "on conflict (key) do nothing; -- never overwrite prices edited in admin",
  "",
];
writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log("wrote supabase/seed.sql");
